package com.smartmart.order.entity; import com.smartmart.user.entity.User; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="orders") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class CustomerOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) private User user; @Column(nullable=false,precision=12,scale=2) private BigDecimal totalAmount; @Column(precision=12,scale=2) private BigDecimal subtotalAmount; @Column(precision=12,scale=2) private BigDecimal deliveryFee; @Enumerated(EnumType.STRING) private PaymentStatus paymentStatus; @Enumerated(EnumType.STRING) private DeliveryStatus deliveryStatus; @Enumerated(EnumType.STRING) private OrderStatus status; @CreationTimestamp private LocalDateTime createdAt; @Column(length=120) private String deliveryName; @Column(length=30) private String deliveryMobile; @Column(length=500) private String deliveryAddress; @Column(length=120) private String deliveryCity; @Column(length=20) private String deliveryPinCode; @Column(length=500) private String deliveryInstructions; @Builder.Default @OneToMany(mappedBy="order",cascade=CascadeType.ALL) private List<OrderItem> items=new ArrayList<>();}
